function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
  return liveCells.filter((other) => isNeighborOf(cell, other)).length;
}

function isNeighborOf([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  const isSameCell = otherX === x && otherY === y;
  const isWithinOneStep =
    Math.abs(otherX - x) <= 1 && Math.abs(otherY - y) <= 1;

  return isWithinOneStep && !isSameCell;
}
